// Пины управления Мотором A
const int IN1 = 2;
const int IN2 = 3;

// Пины управления Мотором B
const int IN3 = 4;
const int IN4 = 5;

void setup() {
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
}

void loop() {
  // 1. Оба мотора вперед на максимальной скорости (255)
  motorA(255);
  motorB(255);
  delay(2000); // Крутим 2 секунды

  // 2. Остановка
  motorA(0);
  motorB(0);
  delay(1000);

  // 3. Оба мотора назад на половинной скорости (-128)
  motorA(-128);
  motorB(-128);
  delay(2000);

  // 4. Разворот на месте (один вперед, другой назад)
  motorA(200);
  motorB(-200);
  delay(1500);

  // 5. Полная остановка перед повтором цикла
  motorA(0);
  motorB(0);
  delay(2000);
}
